-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "deDE" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.mop.monk.brewmaster.Name"] = "Empfohlen"
L["rm.mop.monk.brewmaster.Description"] = "Automatisch gewählt in der Spezialisierung Braumeister. Hält Beinarbeit mit Blackout-Tritt aufrecht, nutzt Fasshieb, wann immer sein Chi passt, Schadensumleitung, wenn Sie verletzt sind (sofort unter 35 %), Hieb, um Energie auszugeben, Tigerklaue für Kraft des Tigers und als kostenlosen Füller (Hieb baut vor Stufe 34 Chi auf) und Berührung des Todes, wenn sie nutzbar ist. Aus der Distanz außerhalb des Kampfes: Chiwelle, Benebelnde Dämpfe, Aufprall oder Fasshieb. Gegen drei oder mehr Gegner: Rauschender Jadewind, Feuerodem und Wirbelnder Kranichtritt nur, solange Beinarbeit noch Zeit hat. Erinnerungen: Der starke Ochse, Vermächtnis des Kaisers, Reinigendes Gebräu bei Schwerer Staffelung (Moderate Staffelung, wenn Beinarbeit Vorrat hat), Flüchtiges Gebräu ab sechs Stapeln, Schutz mit Mächtigem Schutz, Chigebräu, Xuen, Stärkendes Gebräu, Schaden dämpfen oder Magiediffusion bei niedriger Gesundheit, Speerhandstoß. Die Erinnerung an die Statue des Schwarzen Ochsen ist deaktiviert; Schaden abwenden, Zenmeditation und Provokation bleiben Ihnen überlassen."
L["rm.mop.monk.brewmaster.offensive.Name"] = "Schaden zuerst (Simulation)"
L["rm.mop.monk.brewmaster.offensive.Description"] = "Eine Alternative zur integrierten Braumeister-Rotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die andere, oder erhöhen Sie ihre Priorität. Folgt der Schaden-zuerst-Liste des Simulators für einen Tank, dessen Ausrüstung dem Inhalt überlegen ist: Rauschender Jadewind vor Fasshieb, Chi geht für Schaden in Blackout-Tritt, und kein routinemäßiges Reinigendes Gebräu oder Schutz (Reinigendes Gebräu leuchtet nur beim Proc von Reinigung aus dem Set von Tier 15 auf). Flüchtiges Gebräu, Chigebräu, Xuen und Stärkendes Gebräu bleiben Erinnerungen."
L["rm.mop.monk.mistweaver.Name"] = "Empfohlen"
L["rm.mop.monk.mistweaver.Description"] = "Automatisch gewählt in der Spezialisierung Nebelwirker. Mit einem freundlichen Ziel heilt sie dieses Ziel: Erneuernder Nebel bei Abklingzeit-Ende, Erbauung, wenn drei oder mehr Verbündete in der Nähe verletzt sind, Schadensumleitung und Ihr Chi-Talent für Chi, Rauschender Jadewind oder Wirbelnder Kranichtritt für eine verletzte Gruppe, Wallender Nebel bei fünf Stapeln Lebensspendender Nebel, Beruhigender Nebel, wenn das Ziel unter 80 % ist, dann Einhüllender Nebel und Wallender Nebel innerhalb dieser Kanalisierung. Mit einem feindlichen Ziel kämpft sie im Nahkampf (Fistweaving): Tigerklaue und Blackout-Tritt bei Muskelgedächtnis, um Kraft des Tigers und Schlangeneifer zu halten, Blackout-Tritt bei vollem Chi, Wallender Nebel bei fünf Stapeln Lebensspendender Nebel, Erneuernder Nebel und Schadensumleitung für Chi, Hieb. Erinnerungen: Die weise Schlange, Vermächtnis des Kaisers, die Statue der Jadeschlange in einer Gruppe, Manatee in ruhigen Momenten, Donnerfokustee, Chigebräu, Lebenskokon auf einen Verbündeten unter 35 %, Xuen, Entgiftung, Defensivfähigkeiten, Speerhandstoß. Wen Sie heilen, entscheiden Sie; Belebung (Erinnerung deaktiviert) und Heilende Sphäre bleiben Ihnen überlassen."
L["rm.mop.monk.unspecialized.Name"] = "Vor einer Spezialisierung"
L["rm.mop.monk.unspecialized.Description"] = "Für Stufe 1 bis 9 oder jeden Mönch, der keine Spezialisierung gewählt hat; die integrierte Rotation einer Spezialisierung übernimmt, sobald Sie eine wählen. Hält Der wilde Tiger und Kraft des Tigers aufrecht, gibt zwei Chi für Blackout-Tritt aus, nutzt Schadensumleitung, wenn Sie verletzt sind, und sonst Hieb."
L["rm.mop.monk.windwalker.Name"] = "Empfohlen"
L["rm.mop.monk.windwalker.Description"] = "Automatisch gewählt in der Spezialisierung Windläufer. Berührung des Todes, wenn nutzbar, Tigerklaue, um Kraft des Tigers zu halten, Tritt der aufgehenden Sonne bei Abklingzeit-Ende, Chiwelle, Procs von Combobrecher, Furorfäuste, wenn Sie stillstehen und die Kanalisierung Ihre Energie nicht ans Maximum bringt, Hieb, wenn zwei Chi fehlen (stattdessen Schadensumleitung bei Verletzung), Blackout-Tritt, ohne dem nächsten Tritt der aufgehenden Sonne das Chi zu nehmen. Gegen zwei oder mehr Gegner hält Tritt der aufgehenden Sonne seinen Schwächungszauber aufrecht, und ab drei kommen Wirbelnder Kranichtritt oder Rauschender Jadewind hinzu. Erinnerungen: Der wilde Tiger, Vermächtnis des Kaisers und des Weißen Tigers, Tigeraugengebräu bei 19 Stapeln (15 mit Chi zum Ausgeben, 10 während Kampfrausch oder gegen Ende eines Kampfes), Belebendes Gebräu bei wenig Energie, Chigebräu, Xuen, Sturm, Erde und Feuer gegen zwei Gegner (Sie wirken es auf den zweiten), Karmaberührung, Defensivfähigkeiten und Speerhandstoß. Prüfungen auf maximale Energie sind Energieschwellen, passen Sie sie also an Ihr Tempo an."
L["rm.mop.monk.windwalker.simc.Name"] = "SimulationCraft 5.4.8 (Hekili und MaxDps)"
L["rm.mop.monk.windwalker.simc.Description"] = "Eine Alternative zur integrierten Windläufer-Rotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die andere, oder erhöhen Sie ihre Priorität. Die ursprüngliche SimulationCraft-Liste, die die Addons Hekili und MaxDps mitliefern: Kraft des Tigers bei drei Sekunden erneuert, Tritt der aufgehenden Sonne zuerst, solange sein Schwächungszauber fehlt, Furorfäuste für Tigeraugengebräu aufgespart (aktiv oder 15 Stapel), Tigeraugengebräu bei 20 Stapeln oder bei 15 mit Chi und beiden aktiven Stärkungszaubern. Gegen drei oder mehr Gegner gibt sie für Wirbelnder Kranichtritt aus, nutzt Tritt der aufgehenden Sonne nur bei vollem Chi und sammelt Energie unter 60."
L["rm.retail.monk.brewmaster.Name"] = "Blizzard-Kampfassistent mit Gebräuen"
L["rm.retail.monk.brewmaster.Description"] = "Empfohlen für Braumeister. Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Der Kampfassistent drückt keine Gebräue, daher sind die Gebräue, wie Icy Veins rät, Erinnerungen daneben: Schwarzochsengebräu, Niuzao den Schwarzen Ochsen beschwören, Reinigendes Gebräu, Himmlisches Gebräu oder Himmlische Infusion und Berührung des Todes leuchten im Kampf auf, sobald sie bereit sind (Rotation Master kann Staffelung noch nicht auslesen, daher bleibt es Ihre Entscheidung, wie schwer sie wiegt). Außerdem Speerhandstoß bei einem unterbrechbaren Zauber sowie Stärkendes Gebräu und Ihre Volksfähigkeit, wann immer sie im Kampf bereit sind; gegnerische Zauber sind im Kampf verborgen, daher leuchtet die Unterbrechung nur dort auf, wo das Spiel sie anzeigt, und die Gesundheit ist unter Retail verborgen, daher bleibt der Einsatz von Stärkendem Gebräu Ihnen überlassen."
L["rm.retail.monk.brewmaster.guide.Name"] = "Referenz (Icy Veins)"
L["rm.retail.monk.brewmaster.guide.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Priorität von Icy Veins für Braumeister (SimulationCraft stimmt in der Form überein). Blackout-Combo, Leeres Fass und Aufladungen sind im Kampf in Midnight verborgen, daher kann sie dort nicht laufen. Zieht mit Fasshieb. Blackout-Tritt; Chistoß (Meister der Harmonie); Tigerklaue bei Blackout-Combo; Fasshieb bei vollen Aufladungen oder mit Leerem Fass; Feuerodem; Rauschender Jadewind vor Explodierendem Fässchen; Chistoß (Shado-Pan); Fasshieb; Rauschender Jadewind und Wirbelnder Kranichtritt gegen drei oder mehr Gegner; Tigerklaue; Schadensumleitung. Erinnerungen: Schwarzochsengebräu, sobald Reinigendes und Himmlisches Gebräu verbraucht sind, Niuzao den Schwarzen Ochsen beschwören, Reinigendes Gebräu, Himmlisches Gebräu oder Himmlische Infusion, Berührung des Todes, dazu die Erinnerungen an Hilfsfähigkeiten."
L["rm.retail.monk.initial.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.monk.initial.Description"] = "Empfohlen, bevor Sie eine Spezialisierung wählen (solange das Spiel die Anfangsspezialisierung des Mönchs meldet). Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben die Erinnerungen, die jede integrierte Mönch-Rotation teilt, jeweils sobald Sie den Zauber kennen. Wenn Sie auf Stufe 10 eine Spezialisierung wählen, übernehmen die integrierten Rotationen dieser Spezialisierung."
L["rm.retail.monk.mistweaver.Name"] = "Referenz (Icy Veins)"
L["rm.retail.monk.mistweaver.Description"] = "Nur als Referenz, standardmäßig deaktiviert. Blizzard bietet keine Kampfassistent-Liste für Heiler, und im Kampf in Midnight sind die Gesundheit Ihrer Verbündeten, Aufladungen von Erneuernder Nebel, Stapel von Manatee und Procs für Addons verborgen, daher sind Heilempfehlungen nicht möglich; wählen Sie Ihre Heilungen selbst. Bei einem feindlichen Ziel schlägt sie den Fistweaving-Füller vor: Tritt der aufgehenden Sonne, Blackout-Tritt und Tigerklaue; bei einem freundlichen Ziel oder ohne Ziel schlägt sie nichts vor. Erinnerungen: Speerhandstoß sowie Stärkendes Gebräu und Ihre Volksfähigkeit, wann immer sie im Kampf bereit sind."
L["rm.retail.monk.windwalker.Name"] = "Blizzard-Kampfassistent"
L["rm.retail.monk.windwalker.Description"] = "Empfohlen für Windläufer. Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt (er beachtet Meisterschaft: Comboschläge bereits); sie wartet, während Sie wirken oder kanalisieren. Daneben Erinnerungen an das, was der Kampfassistent Ihnen überlässt: Zenit, Erhabene Leitung, Xuen den Weißen Tiger beschwören und Karmaberührung im Kampf, Speerhandstoß bei einem unterbrechbaren Zauber sowie Stärkendes Gebräu und Ihre Volksfähigkeit, wann immer sie im Kampf bereit sind. Gegnerische Zauber sind im Kampf verborgen, daher leuchtet die Unterbrechung nur dort auf, wo das Spiel sie anzeigt; die Gesundheit ist unter Retail verborgen, daher bleibt der Einsatz von Stärkendem Gebräu Ihnen überlassen."
L["rm.retail.monk.windwalker.guide.Name"] = "Referenz (Icy Veins und SimulationCraft)"
L["rm.retail.monk.windwalker.guide.Description"] = "Nur als Referenz, standardmäßig deaktiviert: die Priorität von Icy Veins für Leitung der Erhabenen. Jeder Schritt beachtet Comboschläge (nie der zuletzt gewirkte Zauber); Chi und Ihre eigenen Zauber bleiben auslesbar, aber Herz der Jadeschlange, Zenit, Blackout-Tritt! und Chi-Jis Tanz sind im Kampf in Midnight verborgen, daher kann sie dort nicht laufen; Energie ist unter Retail verborgen, daher entfällt die Tigerklaue vor dem Energiemaximum. Wirbelnder Drachenschlag, wenn Xuen erst in mehr als 10 Sekunden bereit ist; Zenitstampfen bei wenig Chi oder wenn Zenit endet; Erhabene Leitung ohne Herz; Furorfäuste, wenn Herz endet; Erhabene Leitung, Xuen den Weißen Tiger beschwören, Furorfäuste, Wirbelnder Drachenschlag, Schlag des Windlords; Blackout-Tritt, wenn das Chi für Furorfäuste nicht reicht; Tritt des aufziehenden Windes, Tritt der aufgehenden Sonne; Blackout-Tritt bei zwei Aufladungen von Blackout-Tritt! oder während Zenit; Wirbelnder Kranichtritt während Zenit oder bei Chi-Jis Tanz; Berührung des Todes; Tigerklaue, Blackout-Tritt, Schneidende Winde als Füller. Erinnerung: Karmaberührung, dazu die Erinnerungen an Hilfsfähigkeiten."
